INSERT INTO `wp_aioseo_cache` VALUES (24,'newsroom_feed','[{\"id\":1179104,\"title\":\"Fix your SEO inside Elementor, Divi, and WPBakery with TruSEO\",\"excerpt\":\"If you build in Elementor, Divi, or WPBakery, AIOSEO 5.0.4 highlights SEO issues right inside popular page builders. Typos take 1 click to fix, and AI suggestions drop straight into your content.\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/truseo-page-builders\\/\",\"date\":\"2026-10-21T22:17:26+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"5.0.4\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2026\\/10\\/TruSEO-Page-Builders-Featured-Image-selection-300x167.png\",\"callout\":[]},{\"id\":1110156,\"title\":\"TruSEO for Taxonomies: Get SEO Scores for Your Category Pages\",\"excerpt\":\"Category pages, tag archives, and custom taxonomy pages are some of the most visited pages on WordPress sites. And until now, it was nearly impossible to see how well they were optimized. That changes with AIOSEO 5.0.1. TruSEO now works\\u2026\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/truseo-for-taxonomies\\/\",\"date\":\"2026-08-26T05:27:21+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"5.0.1.\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2026\\/08\\/truseo-for-taxonomies-featured-300x167.png\",\"callout\":[]},{\"id\":1085667,\"title\":\"Introducing TruSEO 2.0: Real-Time Scoring, New Look, 10+ Languages\",\"excerpt\":\"TruSEO 2.0 is the biggest rebuild TruSEO has ever gotten: real-time scoring, 10+ new languages with per-post control, and a redesigned Optimization tab that finally organizes your score into clear sections.\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/introducing-truseo-2-0\\/\",\"date\":\"2026-07-30T19:43:36+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"5.0.0\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2026\\/07\\/introducing-truseo-20-1-300x167.png\",\"callout\":[]},{\"id\":1085275,\"title\":\"Rewrite Your WordPress Post for Search in 1 Click With AI\",\"excerpt\":\"TruSEO can now rewrite your SEO title, meta description, and content, and fix spelling, all in 1 click.\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/optimize-with-ai\\/\",\"date\":\"2026-07-30T19:42:38+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"5.0.0\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2026\\/07\\/optimize-with-ai-announcement-1-300x167.png\",\"callout\":[]},{\"id\":1084326,\"title\":\"Introducing Spell Checker: Catch Typos Before You Publish\",\"excerpt\":\"AIOSEO 5.0.0 introduces a built-in Spell Checker that flags and fixes misspelled words with one click. Custom dictionary and language settings available on all plans.\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/introducing-spell-checker\\/\",\"date\":\"2026-07-30T19:42:11+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"5.0.0\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2026\\/07\\/wordpress-spell-checker-aioseo-300x167.png\",\"callout\":[]},{\"id\":1081420,\"title\":\"TruSEO Highlighter Now Suggests & Applies AI-Powered Fixes\",\"excerpt\":\"AIOSEO 5.0.0 upgrades the TruSEO Highlighter with AI-powered fix suggestions. Click a highlighted issue and apply an AI-generated fix right there in the editor, no more tabbing back and forth to fix what\'s flagged. It\'s included on every plan, Basic through Elite.\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/truseo-highlighter-suggests-fixes\\/\",\"date\":\"2026-07-30T19:41:05+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"5.0.0\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2026\\/07\\/truseo-highlighter-ai-fixes-1-300x167.png\",\"callout\":[]},{\"id\":1083285,\"title\":\"The Headline Analyzer Now Lives Inside Your SEO Score\",\"excerpt\":\"AIOSEO 5.0.0 moves the Headline Analyzer inside your TruSEO score. Edit your headline and watch the score update instantly, then compare versions before you pick a winner.\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/headline-analyzer-in-truseo\\/\",\"date\":\"2026-07-30T19:40:22+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"5.0.0\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2026\\/07\\/headline-analyzer-announcement-1-300x167.png\",\"callout\":[]},{\"id\":1053472,\"title\":\"Event & Job Posting Schema Now Available on All AIOSEO Plans\",\"excerpt\":\"If you run events or post job listings, here\'s how to use event and job posting schema to unlock rich results in Google.\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/event-job-posting-schema-basic\\/\",\"date\":\"2026-07-13T09:27:15+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.9.9\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2026\\/06\\/Event-Job-Posting-Schema-Announcement-2-300x167.png\",\"callout\":[]},{\"id\":1053146,\"title\":\"Meet SEO Alerts: An Early Warning System for Critical Site Issues\",\"excerpt\":\"Most serious SEO problems don\\u2019t announce themselves. You find out the way no one wants to: traffic starts sliding, someone asks why, and you spend an afternoon working backwards trying to figure out what changed. I\\u2019ve seen sites go weeks\\u2026\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/introducing-seo-alerts\\/\",\"date\":\"2026-07-08T10:35:07+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.9.9\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2026\\/06\\/wordpress-seo-alerts-300x167.png\",\"callout\":[]},{\"id\":1039047,\"title\":\"Introducing AIOSEO MCP: Your AI Agents Can Now Work on Your WordPress SEO\",\"excerpt\":\"AIOSEO 4.9.8 introduces MCP support, letting you connect Claude, Cursor, ChatGPT, and other AI agents directly to your WordPress site. Ask your AI to fix your SEO\\u2014 and it actually does it, right from chat. Free for every plan, including Lite.\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/introducing-aioseo-mcp\\/\",\"date\":\"2026-06-17T11:02:42+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.9.8\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2026\\/06\\/aioseo-mcp-featured-300x167.png\",\"callout\":[]},{\"id\":1044143,\"title\":\"Meet GPT Image 2 & Nano Banana 2, Now Built Into AIOSEO\",\"excerpt\":\"AIOSEO 4.9.8 adds 2 new models to the AI Image Generator: GPT Image 2 from OpenAI and Nano Banana 2 from Google, giving you more creative freedom than ever to produce unique images for your WordPress site.\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/gpt-image-2-nano-banana-2\\/\",\"date\":\"2026-06-17T10:34:12+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.9.8\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2026\\/06\\/gpt-image-2-nano-banana-2-aioseo-300x167.png\",\"callout\":[]},{\"id\":1043366,\"title\":\"AIOSEO REST API Is Now Free for All Users, Including Lite\",\"excerpt\":\"Starting with AIOSEO 4.9.8, the REST API is free for every plan, including Lite. The addon is deprecated and merged into core, giving all users full programmatic access to their SEO data over HTTP, no upgrade required.\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/aioseo-rest-api\\/\",\"date\":\"2026-06-17T10:33:38+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.9.8\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2026\\/06\\/REST-API-Now-Free-Featured-Image-Green--300x167.png\",\"callout\":[]},{\"id\":987541,\"title\":\"Generate Schema Markup in Seconds With AI\",\"excerpt\":\"The concept of schema markup is simple. The execution of it is not. But you know it matters. You\\u2019ve seen the star ratings, cooking times, and FAQs that dominate the search results when a site has it. Unfortunately, getting there\\u2026\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/aioseo-4-9-6-release\\/\",\"date\":\"2026-04-22T13:15:00+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.9.6\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2026\\/04\\/aioseo-4-9-6-300x167.png\",\"callout\":[]},{\"id\":893135,\"title\":\"Introducing the SEO Checklist & AI Suite\",\"excerpt\":\"Have you ever finished setting up a plugin and thought, \\u201cOkay, I\\u2019m done with the wizard\\u2026 now what?\\u201d I know the feeling. You want to make sure you\\u2019re getting the most out of your new tool, but with so many\\u2026\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/aioseo-4-9-4-release\\/\",\"date\":\"2026-02-24T14:15:00+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.9.4\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2026\\/02\\/aioseo-4-9-4-300x167.png\",\"callout\":[]},{\"id\":809457,\"title\":\"AI Keyword Report & Redirects for More Plans\",\"excerpt\":\"Want to know who\\u2019s ranking in AI search results? Me too. That\\u2019s why our developers have been working hard to create a tool that both our internal team\\u2014and you\\u2014can use. With AIOSEO 4.9.1, you get a powerful new Keyword Report\\u2026\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/aioseo-4-9-1-release\\/\",\"date\":\"2025-12-16T14:35:52+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.9.1\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2025\\/12\\/aioseo-491-ai-keyword-report-300x171.png\",\"callout\":[]},{\"id\":784513,\"title\":\"Smarter Blocks for Recipes, Products, & Navigation\",\"excerpt\":\"Get ready to transform your website with AIOSEO 4.9.0! This update has one of our most requested features\\u2014a fully-optimized Recipe block\\u2014along with an all-new Product block and a revamp of our much-loved Table of Contents. Whether you\\u2019re sharing recipes, showcasing\\u2026\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/aioseo-4-9-0-release\\/\",\"date\":\"2025-11-27T15:03:47+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.9.0\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2025\\/11\\/aioseo-4-9-0-300x171.png\",\"callout\":[]},{\"id\":742955,\"title\":\"Unleash the Power of AI for Your Website!\",\"excerpt\":\"Today, I\\u2019m thrilled to announce the release of AIOSEO 4.8.8\\u2014our most ambitious and transformative update yet! We\\u2019re bringing the power of AI directly to your fingertips, so you can create, design, and optimize your content faster and smarter than ever\\u2026\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/aioseo-4-8-8-release\\/\",\"date\":\"2025-10-23T13:15:00+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.8.8\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2025\\/10\\/aioseo-488-ai-300x167.png\",\"callout\":[]},{\"id\":691425,\"title\":\"Site Audit for Simplified SEO Diagnostics\",\"excerpt\":\"Tired of guessing why your website isn\\u2019t ranking higher? Do you struggle to pinpoint the exact SEO issues holding you back? This often leads to wasted time, missed opportunities, and frustration. Imagine knowing exactly which pages need attention to drive\\u2026\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/site-audit-announcement\\/\",\"date\":\"2025-08-26T13:30:00+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.8.6\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2025\\/08\\/seo-audit-2-300x167.png\",\"callout\":[]},{\"id\":639640,\"title\":\"AI Content Generator: Supercharge Your Content Creation!\",\"excerpt\":\"Tired of spending hours crafting content, only to struggle with SEO titles, meta descriptions, social media posts, and FAQs? A common challenge many publishers face is creating high-quality, SEO-optimized content. From writing engaging articles to generating effective meta descriptions and\\u2026\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/new-ai-content-generator\\/\",\"date\":\"2025-07-08T13:30:00+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.8.4\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2025\\/07\\/ai-content-generator-1-300x167.png\",\"callout\":[]},{\"id\":589447,\"title\":\"Index Status Report: Get Indexing Data Right Inside WordPress\",\"excerpt\":\"Are you absolutely certain Google is indexing all your content? Here\\u2019s a shocking truth\\u2014a significant portion of your WordPress website could be invisible to Google due to indexing issues. We\\u2019re talking about the majority of your pages and posts not\\u2026\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/introducing-index-status-report\\/\",\"date\":\"2025-05-20T13:30:00+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.8.2\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2025\\/05\\/introducing-index-status-report-300x167.png\",\"callout\":[]},{\"id\":532688,\"title\":\"Unlock Better SEO Performance: Introducing AIOSEO 4.8.0\'s Advanced Crawl Features\",\"excerpt\":\"We\\u2019re back with another powerful update! AIOSEO 4.8.0 is here, and I\\u2019m so excited to introduce advanced tools to fine-tune your website\\u2019s crawlability, prevent unwanted indexing, and improve performance. Let\\u2019s dive into what\\u2019s new. In This Article Crawl Cleanup Supercharged\\u2026\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/introducing-aioseo-4-8-0-advanced-crawl-features\\/\",\"date\":\"2025-03-11T13:30:00+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.8.0\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2025\\/03\\/announcement-crawl-features-300x167.png\",\"callout\":[]},{\"id\":492479,\"title\":\"Smarter Keyword Rank Tracking & WooCommerce SEO Made Easy!\",\"excerpt\":\"Big news! We\\u2019ve just released AIOSEO 4.7.8, and it\\u2019s loaded with exciting updates you\\u2019re going to love. These enhancements will help you take your SEO game to the next level! Let\\u2019s break it down\\u2026 In This Article Keyword Rank Tracker\\u2026\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/smarter-keyword-rank-tracking-woocommerce-seo-made-easy\\/\",\"date\":\"2025-01-28T14:30:00+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.7.8\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2025\\/01\\/annoucement-krt-woocommerce-seo-300x167.png\",\"callout\":[]},{\"id\":458400,\"title\":\"BuddyPress & Web Stories Integrations + Author SEO Upgrades!\",\"excerpt\":\"We\\u2019ve rolled out several updates and new features this year. And we\\u2019re back with many more new features to help you take your SEO to a whole new level! The top 3 we\\u2019re most excited about are the: With these\\u2026\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/new-aioseo-4-7-6-buddypress-web-stories-integration-author-seo-improvements\\/\",\"date\":\"2024-12-12T14:30:00+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.7.6\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2024\\/12\\/buddypress-google-web-stories-author-seo-300x167.png\",\"callout\":[]},{\"id\":424835,\"title\":\"Revolutionize Your Content Creation with AIOSEO\'s Writing Assistant\",\"excerpt\":\"We\\u2019ve just released version 4.7.4 of AIOSEO, and we\\u2019re beyond excited to unveil a game-changing feature that will completely transform how you create optimized content in WordPress. We call it Writing Assistant! Imagine having a personal assistant by your side,\\u2026\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/new-revolutionize-your-content-creation-with-aioseos-writing-assistant\\/\",\"date\":\"2024-11-05T14:30:00+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.7.4\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2024\\/10\\/writing-assistant-announcement-300x167.png\",\"callout\":[]},{\"id\":405437,\"title\":\"SEO Email Reports and Bulk CSV Imports\\/Exports to Enhance SEO Management\",\"excerpt\":\"We\\u2019re thrilled to announce the release of AIOSEO 4.7.2, bringing 2 powerful features designed to help you optimize your SEO efforts more efficiently: These much-requested tools will give you deeper insights into your site\\u2019s performance and make it easier to\\u2026\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/new-seo-email-reports-and-bulk-csv-imports\\/\",\"date\":\"2024-10-08T13:30:00+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.7.2\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2024\\/10\\/email-report-import-export-300x167.jpg\",\"callout\":[]},{\"id\":388229,\"title\":\"Track Your Keywords Effortlessly in WordPress\",\"excerpt\":\"Would you like to closely monitor how your content is performing for specific keywords? Then, you\\u2019ll be thrilled about our latest feature update! We\\u2019ve listened to your feature requests and are excited to introduce the Keyword Rank Tracker to our\\u2026\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/new-track-your-keywords-effortlessly-in-wordpress-with-aioseo-4-7-0\\/\",\"date\":\"2024-09-10T13:31:22+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.7.0\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2024\\/09\\/keyword-rank-tracker-featured-image-300x167.jpg\",\"callout\":[]},{\"id\":369721,\"title\":\"Powerful New Schema Types and Updates\",\"excerpt\":\"We\\u2019re thrilled to announce the release of AIOSEO 4.6.8! This latest update is packed with exciting new schema types and improvements to existing ones. This update empowers you to enhance your content\\u2019s visibility and engagement in search results. Let\\u2019s dive\\u2026\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/announcing-aioseo-4-6-8-powerful-new-schema-types-and-updates\\/\",\"date\":\"2024-08-13T13:30:00+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.6.8\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2024\\/08\\/announcing-powerful-schema-300x167.jpg\",\"callout\":[]},{\"id\":352843,\"title\":\"New Support for Thrive Architect and SiteOrigin Page Builders\",\"excerpt\":\"Many of you asked, and we listened. That\\u2019s why we\\u2019re so excited to announce page builder integrations for 2 more page builders \\u2013 Thrive Architect and SiteOrigin in AIOSEO 4.6.6. Yes! That\\u2019s right. If you\\u2019re on AIOSEO 4.6.6 and you\\u2026\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/new-support-for-thrive-architect-and-siteorigin-page-builders\\/\",\"date\":\"2024-07-09T13:31:17+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.6.6\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2024\\/07\\/support-for-thrive-architect-and-siteorigin-page-builders-300x167.jpg\",\"callout\":[]},{\"id\":317560,\"title\":\"Easier Site Connection to Google Search Console and Automatic Sitemap Syncing\",\"excerpt\":\"We\\u2019re thrilled to announce a game-changing improvement to how you connect your WordPress site with Google Search Console in AIOSEO! Our latest release streamlined the entire site verification and sitemap submission process, saving you valuable time and effort. Here\\u2019s a\\u2026\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/easier-site-connection-to-google-search-console\\/\",\"date\":\"2024-05-07T13:30:00+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.6.2\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2024\\/05\\/site-connection-gsc-automatic-sitemap-syncing-300x167.jpg\",\"callout\":[]},{\"id\":293404,\"title\":\"Query Arg Monitoring for Improved Crawling and Indexing\",\"excerpt\":\"We\\u2019re so excited to announce the Query Arg Monitor in AIOSEO 4.5.8! The Query Arg Monitor is a much-requested feature born from the shortcomings of our Crawl Cleanup. FYI, Crawl Cleanup is a feature we developed in response to user\\u2026\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/new-query-arg-monitoring-for-improved-crawling-and-indexing\\/\",\"date\":\"2024-03-19T13:05:13+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.5.8\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2024\\/03\\/announcing-query-arg-monitoring-300x167.jpg\",\"callout\":[]}]',0,'2026-11-02 21:03:13','2026-11-01 21:03:13','2026-11-01 21:03:13');
